mapper.sql:
WHERE d.status = '启用'

    AND d.department_id = #{query.departmentId}


    AND d.name LIKE CONCAT('%', #{query.name}, '%')


    AND EXISTS (
        SELECT 1
        FROM source selected_source
        WHERE selected_source.doctor_id = d.id
          AND selected_source.visit_date = #{query.date}
          AND selected_source.status = '正常'
    )

mapper.select:
SELECT d.id, d.name, d.department_id, dep.name AS department, d.title, d.introduction, COALESCE(( SELECT SUM(s.remain_count) FROM source s WHERE s.doctor_id = d.id AND s.status = '正常'
AND s.visit_date = #{query.date}
), 0) AS remain_count FROM doctor d INNER JOIN department dep ON dep.id = d.department_id
ORDER BY d.id ASC LIMIT #{offset}, #{limit}
